// Configuration constants
const (
	AppName        = "UntitledProject"
	DefaultVersion = "1.0.0"
)

// Config holds the application configuration
type Config struct {
	Environment string
	Port        int
	LogPath     string
}

// InitializeEnvironment sets up the environment and validates OS constraints
func InitializeEnvironment() (*Config, error) {
	if runtime.GOOS != "linux" {
		return nil, fmt.Errorf("unsupported operating system: %s", runtime.GOOS)
	}

	home, err := os.UserHomeDir()
	if err != nil {
		return nil, fmt.Errorf("failed to get home directory: %w", err)
	}

	config := &Config{
		Environment: os.Getenv("APP_ENV"),
		LogPath:     fmt.Sprintf("%s/%s.log", home, AppName),
	}

	if config.Environment == "" {
		config.Environment = "development"
	}

	return config, nil
}

// GetSystemStatus returns a string describing the current system state
func GetSystemStatus() string {
	return fmt.Sprintf("Running on %s (%s)", runtime.GOOS, runtime.GOARCH)
}

